<?php
require dirname(__DIR__,3).'/app/payment_gateway.php';$u=require_user();require_method('GET');$ref=(string)($_GET['ref']??'');if(!preg_match('/^TDC-[A-F0-9]{24}$/',$ref))json_out(['error'=>'Invalid payment reference.'],422);
$q=db()->prepare('SELECT local_reference,requested_gbp,currency,gateway,status,created_at FROM topup_payments WHERE local_reference=? AND user_id=?');$q->execute([$ref,$u['id']]);$p=$q->fetch();if(!$p)json_out(['error'=>'Payment not found.'],404);
$state=pay_refresh($ref);$q=db()->prepare("SELECT COALESCE(SUM(CASE WHEN status='posted' THEN amount ELSE 0 END),0) FROM wallet_ledger WHERE user_id=?");$q->execute([$u['id']]);json_out(['reference'=>$ref,'status'=>$state['status'],'amount'=>(float)$p['requested_gbp'],'currency'=>'EUR','provider_currency'=>$p['currency'],'gateway'=>$p['gateway'],'balance'=>(float)$q->fetchColumn()]);
